	('b156b6f8-accb-49e2-9dba-6b17e0387e7c', '88c7af2e-afd4-4504-a43f-b14cc45d6263', 'product.updated', 'product', 'df4f9162-0cf0-4ca2-8f8f-cc1857869a28', '{"changes": {"sku": "BK-GENE-THEM-3051", "name": "General Themed Coloring Book", "slug": "general-themed-coloring-book", "status": "published", "cost_price": 2900, "updated_at": "2026-09-24T17:51:41.448Z", "description": "- 25 pages of fun : Random themes and designs. \n- Important note : We release one specific 25-page design each month. If you order multiple \"General Themed\" copies in the same month, you will receive multiple copies of the same design.\n- See it in action : Current general-themed copy is pinned as a reel on our page.\n- Availability : Available in Abuja and Lagos, but we deliver nationwide. Inter-state delivery prices are on the website.\n- Delivery time : Within 24 to 48 hours after payment for Abuja and Lagos. 3 to 5 working days for inter-state.", "product_type": "physical", "selling_price": 7000, "requires_customization": false, "supports_theme_customization": false}, "productId": "df4f9162-0cf0-4ca2-8f8f-cc1857869a28", "updatedBy": "a83f4ed6-4a30-4418-800e-58b5df0c35ec", "organizationId": "88c7af2e-afd4-4504-a43f-b14cc45d6263"}', NULL, '2026-09-24 17:51:42.747088+00'),
