	('10ef0d58-5360-4ab2-9089-a316def59179', '88c7af2e-afd4-4504-a43f-b14cc45d6263', 'product.updated', 'product', 'cd2373dd-6a58-4f2d-81ff-7740cad68ab4', '{"changes": {"sku": "BK-VENT-TO-5769", "name": "Vent to me Journal", "slug": "vent-to-me-journal", "status": "published", "cost_price": 9000, "updated_at": "2026-09-25T09:34:24.002Z", "description": "<p><strong>For the thoughts you don’t know what to do with.</strong></p><p>Some days, you don’t need advice. You just need somewhere to put everything.</p><p>Vent to Me gives you a private space to vent freely, understand what you’re feeling and notice the patterns affecting your mood and energy. Use the guided prompts when you need direction, or the open pages when you simply need to write.</p><p><strong>What’s inside</strong></p><ul><li><p>Open writing pages</p></li><li><p>Journaling prompts</p></li><li><p>Daily mood trackers</p></li><li><p>Weekly reflection pages</p></li><li><p>The Energy Pie exercise</p></li><li><p>“Three Things That Didn’t Suck”</p></li><li><p>An affirmation library</p></li></ul><p><strong>Product details</strong></p><ul><li><p>200 pages</p></li><li><p>Premium 100gsm paper</p></li><li><p>Matte hardcover</p></li><li><p>A5 size</p></li><li><p>Designed and printed in Nigeria</p></li></ul><p></p>", "product_type": "physical", "selling_price": 17000, "requires_customization": false, "supports_theme_customization": false}, "productId": "cd2373dd-6a58-4f2d-81ff-7740cad68ab4", "updatedBy": "a83f4ed6-4a30-4418-800e-58b5df0c35ec", "organizationId": "88c7af2e-afd4-4504-a43f-b14cc45d6263"}', NULL, '2026-09-25 09:34:24.774576+00'),
