	('9cbf6918-8f9c-41c4-87ec-05e38f2d8d6c', '88c7af2e-afd4-4504-a43f-b14cc45d6263', 'Positive Affirmation/Mental Health Stickers', 'positive-affirmationmental-health-stickers', '10 Motivational and uplifting phrases. Can be added to your coloring book, journal, planner, phone, bottles or any surface you like. Perfect for personalizing your space, reminding yourself of positive vibes, or gifting to someone special.', 'BK-POSI-AFFI-8765', 'physical', 'published', 700.00, 1500.00, false, '2026-09-14 14:38:26.085043+00', '2026-09-14 14:38:56.974018+00', false),
	('606b8f57-2fcc-4774-a6f1-a18503382832', '88c7af2e-afd4-4504-a43f-b14cc45d6263', '12 Dual Tip Acrylic Markers', '12-dual-tip-acrylic-markers', 'These dual tip acrylic markers feature a fine tip for details and a broad tip for colouring larger areas. Perfect for colouring books, journaling, crafts, and DIY projects.', 'BK-12-DUAL-2672', 'physical', 'published', 6000.00, 9000.00, false, '2026-09-14 14:44:26.413125+00', '2026-09-14 14:44:33.363089+00', false),
	('d06abb88-e31f-4929-9f8c-03df0b11a1dd', '88c7af2e-afd4-4504-a43f-b14cc45d6263', 'Standard Custom Coloring Book  (3 Personal Images And 3 Themes)', 'standard-custom-coloring-book-3-personal-images-and-3-themes', '<ul><li><p>30-page coloring book.  </p></li><li><p>Upload up to 3 personal images to be converted into coloring pages.</p></li><li><p><strong>Pick three themes</strong></p></li><li><p><strong>Production Time</strong> : Ready in 3 working days.</p></li><li><p><strong>Location</strong> : Produced in Abuja.</p></li><li><p><strong>Add ons</strong> : Does not come with coloring tools</p></li></ul><p></p>', 'CUST-STAN-CUST-3599', 'custom', 'published', 6500.00, 12000.00, true, '2026-09-14 15:56:22.877392+00', '2026-09-24 18:05:01.020719+00', true),
	('057f8f82-3a8e-4d21-bf89-89d242f56bf5', '88c7af2e-afd4-4504-a43f-b14cc45d6263', 'Ultimate Game Book', 'ultimate-game-book', '<p>- <strong>What’s Inside </strong>: 20+ Diverse Games | 50 High-quality pages <br />- <strong>50 Pages of Pure Focus</strong>: A curated collection of over 20 unique games.<br />- <strong>The Classics: </strong>Master the favorites including Crosswords, Word Search, Sudoku, Mazes, and Boggle.<br />- <strong>Brain Gym</strong>: Includes Word Ladders, Spot the Difference, and Brain Teasers to keep you sharp.<br />- <strong>We Thought of Everything:</strong> Every book comes with its own pencil and eraser, so you can start playing the second it arrives.</p>', 'BK-ULTI-GAME-6929', 'physical', 'published', 4100.00, 10000.00, false, '2026-09-14 16:05:28.43723+00', '2026-09-24 17:54:42.171727+00', false),
	('df4f9162-0cf0-4ca2-8f8f-cc1857869a28', '88c7af2e-afd4-4504-a43f-b14cc45d6263', 'General Themed Coloring Book', 'general-themed-coloring-book', '<p><strong>- 25 pages of fun</strong> : Random themes and designs.</p><p> <br />- <strong>Important note : We release one specific 25-page design each month. If you order multiple "General Themed" copies in the same month, you will receive multiple copies of the same design.</strong><br />- <strong>See it in action</strong> : Current general-themed copy is pinned as a reel on our page.<br />- <strong>Availability</strong> : Available in Abuja and Lagos, but we deliver nationwide. Inter-state delivery prices are on the website.<br />- <strong>Delivery time</strong> : Within 24 to 48 hours after payment for Abuja and Lagos. 3 to 5 working days for inter-state.</p>', 'BK-GENE-THEM-3051', 'physical', 'published', 2900.00, 7000.00, false, '2026-09-14 16:12:53.128997+00', '2026-09-24 17:58:47.40935+00', false),
	('470586d7-e6f8-400d-beaf-e8b94f6e8f09', '88c7af2e-afd4-4504-a43f-b14cc45d6263', 'Full Custom Coloring Book', 'full-custom-kit-30-personal-images-coloring-tools', '<p>- This kit allows you to add <strong>30</strong> personal images of choice. <br />- You upload the images and we convert them to coloring pages. <br />- It can be images of anything.<br />- <strong>Production Time</strong> : Ready in 3 working days.</p><p><strong>Delivery timeline :</strong></p><p>Abuja: 24–48 hours after production</p><p>All other locations : 3–5 days after production</p>', 'CUST-FULL-CUST-4684', 'custom', 'published', 9000.00, 20000.00, true, '2026-09-14 15:06:15.285919+00', '2026-09-26 05:36:52.966917+00', false),
	('0c708b41-58e9-47ca-97a0-4db6ce07fbf6', '88c7af2e-afd4-4504-a43f-b14cc45d6263', 'Full Custom Kit', 'full-custom-kit', '<p>- This kit allows you to add <strong>30</strong> personal images of choice. <br />- You upload the images and we convert them to coloring pages. <br />- It can be images of anything or anyone.<br />- <strong>Production Time</strong> : Ready in 3 working days.</p><p><strong>Delivery timeline :</strong></p><p><strong>Abuja</strong>: 24–48 hours after production</p><p>All other locations : 3–5 working days after production</p>', 'BNDL-FULL-CUST-9655', 'bundle', 'archived', 9000.00, 25000.00, false, '2026-09-24 18:31:12.230979+00', '2026-09-26 05:27:33.391337+00', false),
	('b5683b13-0df9-4e59-b676-6bd0c99d93b4', '88c7af2e-afd4-4504-a43f-b14cc45d6263', 'Play And Color Kit (Save 1k On Game Book And Unwind Kit)', 'play-and-color-kit-save-1k-on-game-book-and-unwind-kit', '- Game book, general themed coloring book, color pencils, felt pens. 
- Delivered within 24 to 48hrs in Abuja and Lagos. 6 working days for interstate.', 'BK-PLAY-COLO-3441', 'physical', 'draft', 9500.00, 21000.00, false, '2026-09-14 16:16:22.715729+00', '2026-09-15 11:41:18.134386+00', false),
	('82717a1b-b321-4b6d-9af4-f86acf6e7568', '88c7af2e-afd4-4504-a43f-b14cc45d6263', 'Unwind Kit (Save 500 on coloring book and tools)', 'unwind-kit-save-500-on-coloring-book-and-tools', '<p>- Bundle contains : General themed coloring book, pack of 12 coloring pens, pack of 12 felt pens. <br />- Delivered within 24 to 48hrs in Abuja and Lagos. 6 days for inter-state.</p>', 'BNDL-UNWI-KIT-8602', 'bundle', 'published', 5400.00, 11500.00, false, '2026-09-14 16:48:28.31821+00', '2026-09-24 17:46:55.561199+00', false),
	('9e3792e5-9a68-4ea7-9bc2-85f48c36045a', '88c7af2e-afd4-4504-a43f-b14cc45d6263', 'Play And Color Kit (Save 1k On Game Book And Unwind Kit)', 'play-and-color-kit-save-1k-on-game-book-and-unwind-kit-1', '<p>- Game book, general themed coloring book, color pencils, felt pens. <br />- Delivered within 24 to 48hrs in Abuja and Lagos. 6 days for interstate.</p>', 'BNDL-PLAY-COLO-3508', 'bundle', 'published', 9500.00, 21000.00, false, '2026-09-14 16:18:28.847265+00', '2026-09-24 17:49:51.24826+00', false),
	('cd2373dd-6a58-4f2d-81ff-7740cad68ab4', '88c7af2e-afd4-4504-a43f-b14cc45d6263', 'Vent to me Journal', 'vent-to-me-journal', '<p><strong>For the thoughts you don’t know what to do with.</strong></p><p>Some days, you don’t need advice. You just need somewhere to put everything.</p><p>Vent to Me gives you a private space to vent freely, understand what you’re feeling and notice the patterns affecting your mood and energy. Use the guided prompts when you need direction, or the open pages when you simply need to write.</p><p><strong>What’s inside</strong></p><ul><li><p>Open writing pages</p></li><li><p>Journaling prompts</p></li><li><p>Daily mood trackers</p></li><li><p>Weekly reflection pages</p></li><li><p>The Energy Pie exercise</p></li><li><p>“Three Things That Didn’t Suck”</p></li><li><p>An affirmation library</p></li></ul><p><strong>Product details</strong></p><ul><li><p>200 pages</p></li><li><p>Premium 100gsm paper</p></li><li><p>Matte hardcover</p></li><li><p>A5 size</p></li><li><p>Designed and printed in Nigeria</p></li></ul><p></p>', 'BK-VENT-TO-5769', 'physical', 'published', 9000.00, 17000.00, false, '2026-09-24 19:05:25.704041+00', '2026-09-25 18:23:59.010398+00', false),
	('5f4ff4cc-2858-40cc-bc3f-98ea8efe3867', '88c7af2e-afd4-4504-a43f-b14cc45d6263', 'For the Girls 🎀', 'for-the-girls', '<p><strong>Product Description</strong></p><p>A tiny colouring book made specifically for the girls. 🎀</p><p>30 pages of bags, shoes, dresses, perfume, jewellery, flowers, bows, getting-ready moments and all the pretty little things.</p><p>And the best part? <strong>Your name goes on the cover.</strong></p><p><strong>Product Details</strong></p><p>Inside, you get 30 original colouring pages filled with fashion, beauty and little pieces of girlhood, from handbags and heels to perfume, jewellery, flowers and getting-ready moments.</p><p>Each copy is personalised with your name on the cover, making yours completely your own.</p><p><strong>Size: A6</strong></p><p><strong>Pages: 30 colouring pages</strong></p><p><strong>Binding: Top spiral</strong></p><p><strong>Cover: Personalised with your name</strong></p><p><strong>Location : Made in Abuja and will be delivered nationwide.</strong></p><p><strong>Important preorder information</strong></p><p>🎀 <strong>This is a preorder item.</strong></p><p>Preorders close <strong>October 11 at 11:59 PM</strong>.</p><p>All personalised copies will be produced together after preorders close.</p><p><strong>Dispatch begins October 16 from Abuja.</strong></p><p>October 16 is the <strong>dispatch start date, not your delivery date</strong>. Delivery time after dispatch will depend on your location.</p><p>Because each copy is personalised, please make sure the name submitted with your order is correct before checkout.</p><p>Don’t forget to add a name for the cover in the notes section below.</p><p></p><p><strong>Select all 3 themes below to continue with your personalisation 🎀</strong></p>', 'BK-GIRLS-4137', 'physical', 'published', 2000.00, 5500.00, false, '2026-10-01 10:52:45.097442+00', '2026-10-01 17:53:16.692774+00', true);


